<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class AntiBot{private static $blacklist=array('python-requests','python-urllib','python-httpx','curl/','wget/','scrapy/','httpclient/','go-http-client','java/','okhttp','akamai-gbot','semrushbot','mj12bot','ahrefsbot','dotbot','roguecrawler','bingpreview','facebookexternalhit','facebot','quora link preview','linkedinbot','whatsapp','slackbot','telegrambot','discordbot','vkshare','redditbot','quail-search','phantomjs','selenium/','playwright','puppeteer','httpbin.org','nmap scripting engine','nessus',);private static $whitelist=array('baiduspider','googlebot','bingbot','sogou','360spider','yandex','exabot','bytespider','qqbot','yisou',);public static function check($a=array()){$b=self::settingBool('anti_bot.enable',true);if(!$b){return array('ok'=>true,'ua'=>self::ua());}$c=self::settingBool('anti_bot.strict',true);$d=self::ua();$e=strtolower($d);foreach(self::$whitelist as $f){if(strpos($e,$f)!==false){return array('ok'=>true,'ua'=>$d,'whitelist'=>$f);}}foreach(self::$blacklist as $g){if(strpos($e,$g)!==false){if(!$c){return array('ok'=>true,'ua'=>$d,'blacklist'=>$g,'observe'=>true);}$h=isset($a['log'])?$a['log']:true;if($h){self::logBlock($d,self::ip());}if(isset($a['silent'])&&$a['silent']){return array('ok'=>false,'ua'=>$d,'blacklist'=>$g);}http_response_code(403);header('Content-Type: application/json; charset=utf-8');echo json_encode(array('success'=>false,'error'=>'Forbidden'),JSON_UNESCAPED_UNICODE);exit;}}return array('ok'=>true,'ua'=>$d);}public static function watermark(){return'';}public static function verifyApiSign($a,$b,$c='',$d=''){$e=self::settingBool('api_sign.enable',false);if(!$e){return array('ok'=>true,'reason'=>'disabled');}$f=isset($_SERVER['HTTP_X_TIMESTAMP'])?(int)$_SERVER['HTTP_X_TIMESTAMP']:0;$g=isset($_SERVER['HTTP_X_SIGN'])?(string)$_SERVER['HTTP_X_SIGN']:'';if($f<=0||$g===''||$d===''){return array('ok'=>false,'reason'=>'missing sign/timestamp/token');}$h=time();if(abs($h-$f)>300){return array('ok'=>false,'reason'=>'timestamp expired');}$a=strtoupper($a);$i=hash_hmac('sha256',$a.'|'.$b.'|'.$f.'|'.$c,$d);if(!self::secureEquals($i,$g)){return array('ok'=>false,'reason'=>'signature mismatch');}return array('ok'=>true);}public static function ua(){return isset($_SERVER['HTTP_USER_AGENT'])?(string)$_SERVER['HTTP_USER_AGENT']:'';}public static function ip(){foreach(array('HTTP_X_FORWARDED_FOR','HTTP_X_REAL_IP','REMOTE_ADDR')as $a){if(!empty($_SERVER[$a])){$b=explode(',',(string)$_SERVER[$a]);$b=trim($b[0]);if($b!==''&&$b!=='unknown')return $b;}}return'0.0.0.0';}public static function secureEquals($b,$a){if(!function_exists('hash_equals')){return(md5($b)===md5($a));}return hash_equals((string)$b,(string)$a);}private static function settingBool($a,$b=false){try{if(!class_exists('Core\\DB')){return $b;}$c=DB::pdo()->query("SELECT v FROM app_settings WHERE `k`='".DB::pdo()->quote($a)."' LIMIT 1")->fetch();if($c&&$c['v']!==null){$d=(string)$c['v'];return!in_array(strtolower($d),array('0','false','no',''),true);}}catch(\Throwable $f){}return $b;}private static function logBlock($a,$b){try{$c=dirname(__DIR__).'/cache/antibot.log';$d=dirname($c);if(!is_dir($d))@mkdir($d,0750,true);@file_put_contents($c,date('Y-m-d H:i:s')." | {$b} | ".substr($a,0,200)."\n",FILE_APPEND|LOCK_EX);}catch(\Throwable $f){}}}